// Generates src/generated/routes.js from schema/routes.json.
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";

const root = new URL("../", import.meta.url);
const { routes } = JSON.parse(readFileSync(new URL("schema/routes.json", root), "utf8"));
const lines = [
  "// GENERATED by scripts/gen.mjs from schema/routes.json. Do not edit: change the schema and run `node scripts/gen.mjs`.",
  "export const routes = [",
  ...routes.map((r) => `  { method: ${JSON.stringify(r.method)}, path: ${JSON.stringify(r.path)}, handler: ${JSON.stringify(r.handler)} },`),
  "];",
  "",
];
mkdirSync(new URL("src/generated/", root), { recursive: true });
writeFileSync(new URL("src/generated/routes.js", root), lines.join("\n"));
console.log("wrote src/generated/routes.js");
